local _, WFJ = ...
WFJ.Data.add("book", {
  ["188fa9aa8fbca660"] = { "Assetato di potere e ossessionato dall'idea di diventare egli stesso un dio, Gul'dan partì alla disperata ricerca della Tomb of Sargeras, sepolta sotto il mare, che secondo lui custodiva i segreti del potere supremo. Avendo già condannato i suoi fratelli orchi a diventare schiavi della Legione Infuocata, Gul'dan non si curò affatto del presunto dovere verso Doomhammer.", "." },
  ["1897fe0fc3357ea5"] = { "Citazioni\n\n\"Vuoi sapere qualcosa sull'ingegneria goblin? Prova a chiedere a uno dei loro ingegneri più brillanti... mi pare si chiami 'Nubby Stumpfingers'. Vuoi sapere perché si chiama così? QUELLA è l'ingegneria goblin.\"\n\n-- Ringo Tragediction, ingegnere gnomo\n\n\"Dite quello che volete di noi goblin, ma vi dico una cosa: NOI ABBIAMO GLI ESPLOSIVI!\"\n\n-- Yazz Nitrospork, bombardiere goblin", "." },
  ["18bfe6e8af1a7cef"] = { "Lo scavo di Bael Modan\n\nLa prima squadra di rilevamento inviata dalla ⟦Explorers' League=Lega degli Esploratori⟧ aveva davvero ragione nelle sue scoperte. Questo terreno custodisce reperti di valore inestimabile per il nostro popolo. Senza dubbio, sotto la sabbia e la roccia di Bael Modan troveremo molte risposte nella nostra ricerca della conoscenza.\n\nTuttavia, la geologia della regione ci impone di ricorrere a misure estreme. Molti depositi di sabbia si sono solidificati a causa delle dure condizioni e del clima mutevole.", "." },
  ["18c0fe7d81c19ac2"] = { "Con il passare dei mesi, Kel'Thuzad trovò molti volontari entusiasti per il suo nuovo culto tra i lavoratori stanchi e oberati di Lordaeron. Fu sorprendentemente facile per Kel'Thuzad raggiungere il suo scopo: trasformare la fede dei cittadini nella ⟦Holy Light=Luce Sacra⟧ in fede nell'oscura ombra di Ner'zhul. Mentre il Cult of the Damned cresceva in numero e in influenza, Kel'Thuzad si assicurò di nasconderne le attività alle autorità di Lordaeron.", "." },
  ["18ebaf2dfab71d89"] = { "Maestro Carevin,\n\nchi porta questo biglietto ha dimostrato di essere <retto/retta> nella Luce, capace di combattere i non morti e i demoni che infestano i confini di ⟦Duskwood=Boscovespro⟧, e <disposto/disposta> a unirsi alla famiglia Carevin nella sua causa della Luce.\n\nVi suggerirei pertanto di affidare a <questo/questa> combattente della Luce altri incarichi, magari indagare su alcuni cittadini sospettati di dare aiuto ai nemici della Luce.\n\nVostro devoto,\nCalor", "." },
})
